def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    lines = text.splitlines()
    current_section = None
    current_section_data = {}
    sections = {}
    default_keys = {}
    in_quoted_value = False
    interpolation_stack = []

    for line in lines:
        stripped = line.strip()
        if not stripped or (stripped.startswith((';', '#')) and not in_quoted_value):
            continue

