        # Check for section header
        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            if section_name == 'DEFAULT':
                current_section = None
                current_section_data = {}
                continue
            current_section = section_name
            sections[current_section] = {}
            if current_section != 'DEFAULT':
                current_section_data = sections[current_section]
            else:
                current_section_data = {}
            continue

        # Check for key-value pair
        if not current_section:
            raise ValueError("Key line before any section header")

        # Parse key-value pair
        parts = []
        key = None
        value = None
        in_key = True

        # Handle quoted values
        if line.startswith('"'):
            in_quoted_value = True
            value = line[1:].strip()
            if not value.endswith('"'):
                raise ValueError("Unterminated quoted value")
            continue

        # Split on first = or :
        split_pos = min(line.find('='), line.find(':'))
        if split_pos == -1:
            raise ValueError("Malformed key-value pair")

        if split_pos == 0:
            raise ValueError("Key cannot start with = or :")

        key_part = line[:split_pos].strip()
        if not key_part:
            raise ValueError("Empty key")

        key = key_part.lower()
        remaining = line[split_pos:].strip()

        # Handle continuation lines
        if remaining.startswith('"'):
            in_quoted_value = True
            value = remaining[1:].strip()
            if not value.endswith('"'):
                raise ValueError("Unterminated quoted value")
            last_key = key
            continue

        # Check for interpolation
        if remaining.startswith('${'):
            # Handle interpolation
            interpolation_match = re.match(r'^(\${[^}]+})$', remaining)
            if not interpolation_match:
                raise ValueError("Invalid interpolation syntax")
            interp_key = interpolation_match.group(1)[2:-1]

            # Handle section:key syntax
            if ':' in interp_key:
