                resolved_value = default_keys.get(interp_key, '')
            else:
                # Specific section
                resolved_value = sections.get(section_name, {}).get(interp_key, '')

            # Check for cycles
            if resolved_value in interpolation_stack:
                raise ValueError("Interpolation cycle detected")
            interpolation_stack.append(resolved_value)

            # Recursively resolve
            resolved_value = resolve_interpolation(resolved_value, sections, default_keys, current_section)
            interpolation_stack.pop()

            value = resolved_value
            last_key = key
            continue

        # Handle continuation lines
        if remaining.startswith('"'):
            in_quoted_value = True
            value = remaining[1:].strip()
            if not value.endswith('"'):
                raise ValueError("Unterminated quoted value")
            last_key = key
            continue

        # Normal value handling
        if remaining:
            value = remaining
        else:
            value = ''

        # Store key-value pair
        if key in current_section_data:
            # Later value wins
            pass
        else:
            current_section_data[key] = value

        last_key = key

    # Handle DEFAULT section keys
    for section in sections:
        if section == 'DEFAULT':
            continue
        for key, value in default_keys.items():
            if key not in sections[section]:
                sections[section][key] = value

    return sections

def resolve_interpolation(value: str, sections: Dict[str, Dict[str, str]], default_keys: Dict[str, str], current_section: str | None) -> str:
    # Handle interpolation in the value
    result = []
    i = 0
    while i < len(value):
        if value[i] == '${':
            # Find closing brace
            j = value.find('}', i)
            if j == -1:
                raise ValueError("Unterminated interpolation")
            interp_key = value[i+2:j]
            i = j + 1

            # Handle section:key syntax
            if ':' in interp_key:
                section_key = interp_key.split(':')
                section_name = section_key[0]
                interp_key = section_key[1]
            else:
                section_name = current_section
                if section_name == 'DEFAULT':
                    section_name = None

            # Resolve interpolation
            if section_name is None:
                # DEFAULT section
                resolved_value = default_keys.get(interp_key, '')
            else:
                # Specific section
                resolved_value = sections.get(section_name, {}).get(interp_key, '')

            # Recursively resolve
            resolved_value = resolve_interpolation(resolved_value, sections, default_keys, section_name)
            result.append(resolved_value)
        else:
            result.append(value[i])
            i += 1

    return ''.join(result)
