from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0
        }

    def _clean_expired(self):
        now = self.clock()
        expired_keys = []
        for key in list(self.cache.keys()):
            expiry = self.cache[key]["expiry"]
            if expiry <= now:
                expired_keys.append(key)
        for key in expired_keys:
            del self.cache[key]
            self.stats["expirations"] += 1

    def put(self, key, value):
        if self.capacity == 0:
            return

        self._clean_expired()

        if key in self.cache:
            # Update existing entry
            self.cache.move_to_end(key)
            self.cache[key]["value"] = value
            self.cache[key]["expiry"] = self.clock() + self.ttl
        else:
            # Add new entry
            if len(self.cache) >= self.capacity:
                # Evict LRU
                self.cache.popitem(last=False)
                self.stats["evictions"] += 1

            self.cache[key] = {
                "value": value,
                "expiry": self.clock() + self.ttl
            }
            self.cache.move_to_end(key)

    def get(self, key, default=None):
        if self.capacity == 0:
            self.stats["misses"] += 1
            return default

        self._clean_expired()

        if key not in self.cache:
            self.stats["misses"] += 1
            return default

        entry = self.cache[key]
        if entry["expiry"] <= self.clock():
            del self.cache[key]
            self.stats["expirations"] += 1
            self.stats["misses"] += 1
            return default

        self.cache.move_to_end(key)
        self.stats["hits"] += 1
        return entry["value"]

    def __len__(self):
        now = self.clock()
        return sum(1 for entry in self.cache.values() if entry["expiry"] > now)

    def stats(self):
        return self.stats
