from typing import Iterator

def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("Empty or blank string")

    def parse_part(part: str) -> tuple[int, str]:
        if not part:
            raise ValueError("No unit specified")
        try:
            num = int(part[:-1])
        except ValueError:
            raise ValueError("Invalid number format")
        unit = part[-1].upper()
        if unit not in {'H', 'M', 'S'}:
            raise ValueError("Unknown unit")
        return num, unit

    parts = []
    current_part = []
    for char in s:
        if char.isspace():
            if current_part:
                parts.append(''.join(current_part))
                current_part = []
        else:
            current_part.append(char)
    if current_part:
        parts.append(''.join(current_part))

    if not parts:
        raise ValueError("No valid parts found")

    # Check for repeated units and order
    seen_units = set()
    for part in parts:
        num, unit = parse_part(part)
        if unit in seen_units:
            raise ValueError("Repeated units")
        seen_units.add(unit)
        if unit not in {'H', 'M', 'S'}:
            raise ValueError("Invalid unit order")

    total_seconds = 0
    for part in parts:
        num, unit = parse_part(part)
        if unit == 'H':
            total_seconds += num * 3600
        elif unit == 'M':
            total_seconds += num * 60
        elif unit == 'S':
            total_seconds += num

    return total_seconds
