from typing import List

def summarize_ranges(nums: List[int]) -> str:
    if not nums:
        return ""

    nums_sorted = sorted(set(nums))
    result = []
    start = nums_sorted[0]

    for num in nums_sorted[1:]:
        if num == start + 1:
            start = num
        else:
            if start == num - 1:
                result.append(f"{start}-{num}")
            elif start == num:
                result.append(str(start))
            else:
                result.append(f"{start}..{num}")
            start = num

    # Handle the last range
    if start == nums_sorted[-1]:
        result.append(str(start))
    elif start == nums_sorted[-1] - 1:
        result.append(f"{start}-{nums_sorted[-1]}")
    else:
        result.append(f"{start}..{nums_sorted[-1]}")

    return ",".join(result)
